    표8_상담적용: [
        {"상황":"하나님의 약속이 이루어지지 않는 것 같아 실망한 성도", "성경원리":"하나님의 약속은 수백 년의 시간을 초월하여 반드시 이루어진다. 인간의 시간표와 하나님의 시간표는 다르다", "실제적용":"구약 예언들이 그리스도 안에서 어떻게 성취되었는지 함께 살펴보며 하나님의 신실하심을 재확인한다"},
        {"상황":"구약과 신약이 왜 다른지 혼란스러운 신자", "성경원리":"구약과 신약은 하나의 하나님의 이야기다. 구약은 약속이요 신약은 성취다. 두 성경은 그리스도를 통해 완전한 통일성을 가진다", "실제적용":"루가복음 24:27의 예수님의 엠마오 길 가르침처럼 구약에서 그리스도를 발견하는 성경 공부를 함께 한다"},
        {"상황":"현재의 고난으로 하나님의 신실하심을 의심하는 성도", "성경원리":"하나님은 수백 년의 침묵 끝에 약속을 이루시는 분이다. 현재의 고난이 하나님이 약속을 잊으셨다는 증거가 아니다", "실제적용":"이스라엘의 430년 애굽 생활과 출애굽의 성취를 통해 하나님이 고난 중에서도 역사하심을 가르친다"}
    ],
