        {"구절":"눅 24:27", "연결점":"모세와 모든 선지자의 글에서 그리스도에 관한 것을 풀어주심", "구분":"신약"},
        {"구절":"고후 1:20", "연결점":"하나님의 약속은 그리스도 안에서 예스와 아멘이 됨", "구분":"신약"},
        {"구절":"히 1:1-2", "연결점":"선지자들을 통해 말씀하시다가 마지막에 아들로 말씀하심", "구분":"신약"},
        {"구절":"벧전 1:10-12", "연결점":"선지자들이 미리 연구하고 상고한 구원의 은혜", "구분":"신약"}
