        {"새찬송가":"35", "통일찬송가":"35", "제목":"영광을 받으신 만유의 주여", "선정이유":"하나님께 영광을 돌리는 예배의 찬송"},
        {"새찬송가":"575", "통일찬송가":"577", "제목":"감사해 모든 것을", "선정이유":"모든 것에 감사하는 신앙 자세를 노래하는 찬송"},
        {"새찬송가":"1", "통일찬송가":"1", "제목":"만복의 근원 하나님", "선정이유":"하나님께 영광과 감사를 드리는 대표적 찬송"}
