    표9_교차참조: [
        {"구절":"잠 6:16-17", "연결점":"여호와의 미워하시는 것이 교만한 눈과 거짓된 혀와 무죄한 자의 피를 흘리는 손이요", "구분":"구약"},
        {"구절":"삼상 15:23", "연결점":"거역하는 것은 점치는 죄와 같고 완고한 것은 사신 우상에게 절하는 죄와 같음이라", "구분":"구약"},
        {"구절":"출 20:12", "연결점":"네 부모를 공경하라 그리하면 너의 하나님 나 여호와가 네게 준 땅에서 네 생명이 길리라", "구분":"구약"},
        {"구절":"잠 16:18", "연결점":"교만은 패망의 선봉이요 거만한 마음은 넘어짐의 앞잡이니라", "구분":"구약"},
        {"구절":"약 4:6", "연결점":"하나님이 교만한 자를 물리치시고 겸손한 자에게 은혜를 주신다 하였느니라", "구분":"신약"},
        {"구절":"빌 2:3-8", "연결점":"교만한 인간의 죄에 대한 대답으로 그리스도의 겸손과 낮아지심을 제시", "구분":"신약"},
        {"구절":"엡 6:1-3", "연결점":"자녀들아 주 안에서 너희 부모에게 순종하라 이것이 옳으니라 네 아버지와 어머니를 공경하라", "구분":"신약"},
        {"구절":"약 3:9-10", "연결점":"우리가 이것으로 주 아버지를 찬송하고 또 이것으로 하나님의 형상대로 지음을 받은 사람을 저주하나니 한 입에서 찬송과 저주가 나오는도다", "구분":"신약"}
    ]
