        {"대지":"서론", "내용":"당신의 인생에서 가장 귀한 특권은 무엇인가? 학력? 재산? 가문? 바울은 서슴없이 '하나님의 말씀을 맡은 것'이 첫째 특권이라고 답한다", "예화_적용":"세상의 특권 목록과 하나님이 주신 특권을 비교하는 질문으로 서론 열기"},
        {"대지":"1대지: 말씀을 맡은 것이 최고의 특권", "내용":"이 세상 어떤 민족도 하나님의 신탁을 직접 위탁받지 못했다. 이스라엘이 구약을 보존한 것, 교회가 신약을 받은 것은 세계사에 없는 특권", "예화_적용":"성경이 없는 문화권의 사람들과 성경을 가진 우리의 차이"},
        {"대지":"2대지: 위탁은 소유가 아닌 청지기직", "내용":"'맡았다'는 말은 내 것이 아님을 뜻한다. 주인에게 결산해야 하는 청지기의 책임이 따름", "예화_적용":"은행의 수탁 자산은 은행 직원의 것이 아닌 고객의 것임을 비유로"},
        {"대지":"결론", "내용":"성경을 가진 것이 당연하지 않다. 이 특권을 소홀히 여기면 가장 큰 심판을 받을 것이다. 오늘 말씀 앞에 겸손히 서라", "예화_적용":"매일 성경 읽기의 실천을 구체적인 결단으로 제안"}
