        {"상황":"죄를 저지르고도 별 일 없다며 안일한 성도", "성경원리":"하나님은 반드시 세상을 심판하시며 지금 당장 심판받지 않음이 하나님의 의로움을 취소하지 않음 (롬 2:4-5)", "실제적용":"하나님의 오래 참으심이 심판의 부재가 아닌 회개의 기회임을 설명하며 회개를 촉구"}
