        {"대지":"서론", "내용":"'내가 먼저 하나님을 찾았다'고 생각하는가? 성경은 그렇지 않다고 말한다. 자연적 인간은 하나님을 찾지 않는다. 그렇다면 우리가 믿게 된 것은 우리가 하나님을 찾았기 때문이 아니라 하나님이 먼저 우리를 찾으셨기 때문이다", "예화_적용":"요 6:44 '아버지께서 이끌지 아니하시면 아무도 내게 올 수 없느니라'를 서론으로"},
        {"대지":"1대지: 자연인은 영적으로 깨닫지 못한다", "내용":"고전 2:14 '육에 속한 사람은 하나님의 성령의 일을 받지 아니하나니'. 영적 진리는 성령의 조명 없이 이해될 수 없음", "예화_적용":"영적으로 눈먼 사람에게 아무리 성경을 설명해도 모르는 것은 능력의 문제가 아닌 본질의 문제"},
        {"대지":"2대지: 하나님이 먼저 찾아오신다", "내용":"하나님을 찾는 자가 없으므로 구원의 시작은 항상 하나님의 주도. 잃은 양을 찾는 목자처럼 하나님이 먼저 찾아오심", "예화_적용":"눅 19:10 '인자가 온 것은 잃어버린 자를 찾아 구원하려 함이니라'를 핵심으로"},
        {"대지":"결론", "내용":"당신이 지금 교회에 있다면 그것은 당신이 찾은 것이 아니라 하나님이 먼저 찾으신 것이다. 이 은혜를 깨닫고 하나님의 부르심에 응답하라", "예화_적용":"어린 시절 신앙의 씨앗이 어디서 왔는지 돌아보며 하나님의 선행하는 은혜를 감사함"}
