        {"상황":"폭력 피해로 하나님의 보호하심을 의심하는 성도", "성경원리":"하나님은 생명을 귀하게 여기시며 폭력에 분노하시는 분이심. 고난 속에서도 함께하심 (시 34:18)", "실제적용":"하나님의 임재 안에서 상처를 처리하는 치유 기도와 전문 트라우마 상담을 통해 회복 과정을 함께함"}
