        {"상황":"율법 공부를 많이 했는데 삶이 변화되지 않아 답답한 성도", "성경원리":"율법은 죄를 깨닫게 하는 기능이 있으나 (롬 3:20) 변화는 성령의 능력으로 이루어짐", "실제적용":"율법 지식을 성령의 능력을 구하는 기도로 연결하고 말씀이 삶에 적용되는 구체적 방법을 함께 탐색"}
