        {"대지":"1대지: 질문 - 할례 이전인가 이후인가?", "내용":"만일 할례 이후라면 칭의는 할례(의식)에 달린 것. 만일 할례 이전이라면 칭의는 의식과 무관한 것. 바울은 성경이 이 질문에 명확히 답한다고 말함", "예화_적용":"원인과 결과의 순서를 확인하는 논리"},
        {"대지":"2대지: 답 - 무할례시, 즉 이방인의 상태에서", "내용":"창 15장(칭의) → 창 17장(할례) = 명백히 할례 이전. 따라서 의롭다 하심은 할례와 무관하고 이방인의 상태에서 이루어진 것. 이것은 이방인도 같은 믿음으로 의롭다 하심을 받을 수 있음의 근거", "예화_적용":"아브라함은 할례받기 전에 이미 하나님 앞에서 의롭다 하심을 받은 이방인이었음"},
        {"대지":"결론", "내용":"아브라함의 칭의는 무할례시, 즉 이방인의 상태에서였다. 이것은 하나님의 섭리적 계획이다. 모든 믿는 자가 아브라함과 같은 믿음으로 의롭다 하심을 받을 수 있도록", "예화_적용":"하나님의 구속사적 설계의 정교함"}
