        {"대지":"서론", "내용":"아브라함이 믿은 하나님은 어떤 분인가? 바울은 두 가지 놀라운 속성을 제시한다: 죽은 자를 살리시는 분, 없는 것을 있는 것같이 부르시는 분. 이 하나님을 믿는 것이 바로 구원의 믿음이다", "예화_적용":"말씀 한 마디로 우주를 창조하신 분 - 그 능력이 구원에도 역사함"},
        {"대지":"1대지: 죽은 자를 살리시는 하나님", "내용":"아브라함의 죽은 몸과 사라의 죽은 태에서 이삭을 주신 하나님. 예수를 죽음에서 살리신 하나님. 우리의 영적 죽음에서 우리를 살리신 하나님. 죽음은 하나님의 능력을 막지 못함", "예화_적용":"에스겔의 마른 뼈 환상 (겔 37장) - 죽은 것에서 생명이"},
        {"대지":"2대지: 없는 것을 있는 것같이 부르시는 하나님", "내용":"창조 시 말씀으로 없는 것을 있게 하신 분. 아직 없는 이삭을 이미 있는 것처럼 선언하신 분. 우리를 의롭다 하시는 것도 동일한 창조적 선언. 칭의는 창조주의 선언", "예화_적용":"하나님의 말씀은 현실을 바꾸는 창조적 능력"},
        {"대지":"결론", "내용":"아브라함이 믿은 하나님, 우리가 믿는 하나님은 죽은 자를 살리시며 없는 것을 있게 하시는 분이다. 이 하나님 앞에서 우리의 모든 불가능은 없어진다", "예화_적용":"롬 8:31 만일 하나님이 우리를 위하시면 누가 우리를 대적하리요"}
