        {"교리":"칭의의 근거로서의 믿음", "설명":"믿음이 의로 여기심을 받음은 믿음 자체에 공로가 있어서가 아니라 하나님이 그 믿음을 의로 간주하시기 때문. 칭의의 도구적 원인은 믿음, 질료적 원인은 그리스도의 의", "관련구절":"롬 3:22; 빌 3:9"}
