pastorCommentaryData["로마서_4_23"] = {
    본문: "의로 여기셨다 기록된 것은 아브라함만 위한 것이 아니요",
    표1_원어분석: [
        {"원어":"Οὐκ ἐγράφη δὲ δι' αὐτὸν μόνον (욱 에그라페 데 디 아우톤 모논)", "의미_문법":"아브라함만 위하여 기록된 것이 아니다 - 에그라페는 그라포(γράφω) 부정과거 수동태. 성경이 기록된 목적을 말함", "설교포인트":"성경은 과거 인물의 이야기가 아니라 모든 세대를 위한 말씀"},
        {"원어":"ὅτι ἐλογίσθη αὐτῷ (호티 엘로기스데 아우토)", "의미_문법":"이것이 저에게 의로 여기셨다 - 창 15:6이 계속 인용됨. 23-24절이 아브라함의 경우를 우리에게 적용", "설교포인트":"성경의 일반화 - 아브라함의 경우가 모든 믿는 자에게 적용됨"}
    ],
    표2_역사적배경: [
        {"항목":"성경 기록의 목적", "내용":"바울은 성경이 단순히 역사 기록이 아니라 모든 세대를 위한 교훈으로 기록되었다고 봄. 롬 15:4 무릇 전에 기록한 바는 우리의 교훈을 위하여 기록된 것이니. 구약의 아브라함 이야기는 신약 성도들을 위한 것이기도 함", "목회적활용":"성경을 오늘 우리에게 적용하는 성경해석학"},
        {"항목":"아브라함의 사례의 보편성", "내용":"아브라함 한 개인의 이야기에서 모든 믿는 자에게 적용되는 원리 도출. 이것이 바울의 성경 해석 방법 - 한 사례에서 보편 원리를 도출하여 현재 상황에 적용", "목회적활용":"성경 이야기를 오늘 우리에게 적용하는 설교 방법론"}
    ],
    표3_신학적의미: [
        {"교리":"성경의 적용성", "설명":"성경은 특정 시대 특정 인물만을 위해 기록된 것이 아님. 아브라함의 칭의 기사는 모든 믿는 자에게 적용되는 보편 원리를 담고 있음. 성경의 시의성(時宜性)과 보편성", "관련구절":"롬 15:4; 딤후 3:16"},
        {"교리":"칭의의 지속성", "설명":"아브라함 때나 지금이나 동일한 방법(믿음)으로 의롭다 하심을 받음. 칭의의 방법이 역사를 통해 변하지 않음. 구약도 신약도 동일한 복음 원리", "관련구절":"히 13:8; 갈 3:8"}
    ],
    표4_예표론: [
        {"구분":"아브라함의 칭의 → 모든 믿는 자의 칭의", "내용":"아브라함의 칭의 기사는 그 후에 올 모든 믿는 자의 칭의의 예표이자 원형으로 기록됨", "그리스도연결":"24절 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿는 자의 칭의로 완성됨"}
    ],
    표5_매튜헨리: [
        {"영어원문":"Now it was not written for his sake alone, that it was imputed to him. What was recorded of Abraham's justification was not merely his personal history but written for all who would believe.", "한국어번역":"이것이 그에게만 의로 여기셨다고 기록된 것이 아니다. 아브라함의 칭의에 대해 기록된 것은 단지 그의 개인적 역사가 아니라 믿을 모든 자들을 위해 기록된 것이다.", "핵심통찰":"성경 기록의 보편적 목적 - 과거 한 인물만이 아닌 모든 세대를 위함"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"아브라함만을 위한 것이 아니다 - 성경의 보편적 적용 (롬 4:23)", "예화_적용":"아브라함의 이야기가 오늘 나의 이야기가 됨"},
        {"대지":"서론", "내용":"성경이 왜 아브라함 이야기를 그렇게 자세히 기록했을까? 바울은 그것이 아브라함만을 위한 것이 아니라 우리를 위한 것이라고 말한다. 성경의 모든 이야기에는 우리를 향한 목적이 있다", "예화_적용":"편지는 수신자만을 위한 것이지만 성경은 모든 세대를 위한 것"},
        {"대지":"1대지: 기록의 목적 - 아브라함만이 아님", "내용":"성경은 아브라함의 개인 이야기가 아니라 모든 믿는 자를 위한 신앙 교훈. 딤후 3:16 모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익함", "예화_적용":"교과서는 특정 학생만이 아닌 모든 학생을 위해 쓰임"},
        {"대지":"2대지: 보편화의 논리", "내용":"아브라함의 사례에서 원리를 도출하여 모든 믿는 자에게 적용. 아브라함이 믿음으로 의롭다 하심을 받았다면, 같은 믿음을 가진 모든 자도 동일하게 의롭다 하심을 받음", "예화_적용":"법 조항이 모든 해당 사례에 동일하게 적용되듯"},
        {"대지":"결론", "내용":"아브라함의 칭의 이야기는 나의 이야기다. 성경이 이것을 기록한 것은 바로 나를 위한 것이다. 오늘 나도 아브라함처럼 믿음으로 의롭다 하심을 받을 수 있다", "예화_적용":"롬 15:4 전에 기록한 바는 우리의 교훈을 위하여 기록된 것이니"}
    ],
    표7_찬송가: [
        {"새찬송가":"201", "통일찬송가":"242", "제목":"성경은 하나님의 말씀이니", "선정이유":"성경은 모든 세대를 위해 기록된 하나님의 말씀"},
        {"새찬송가":"200", "통일찬송가":"241", "제목":"하나님의 말씀은", "선정이유":"보편적으로 적용되는 하나님의 말씀의 능력"},
        {"새찬송가":"208", "통일찬송가":"239", "제목":"내 영혼이 은총 입어", "선정이유":"성경 말씀이 나에게 직접 적용되는 은혜"}
    ],
    표8_상담적용: [
        {"상황":"성경의 이야기가 자신과 관계없다고 느끼는 성도", "성경원리":"의로 여기셨다 기록된 것은 아브라함만을 위한 것이 아님 (롬 4:23). 성경은 나를 위해 기록됨", "실제적용":"아브라함의 이야기가 현대 우리에게 어떻게 적용되는지 구체적으로 연결하며 성경을 나의 이야기로 읽는 방법을 가르침"},
        {"상황":"믿음의 선조들의 경험이 자신에게는 해당되지 않는다고 생각하는 성도", "성경원리":"성경 기록이 보편적으로 적용됨 (롬 4:23-24). 아브라함의 칭의의 원리가 오늘도 동일함", "실제적용":"하나님이 동일하시며 믿음의 원리도 동일함을 가르치고 아브라함처럼 믿음으로 나아갈 수 있음을 격려"}
    ],
    표9_교차참조: [
        {"구절":"롬 15:4", "연결점":"무릇 전에 기록한 바는 우리의 교훈을 위하여 기록된 것이니 - 성경 기록의 보편적 교훈 목적", "구분":"신약"},
        {"구절":"딤후 3:16", "연결점":"모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익하니", "구분":"신약"},
        {"구절":"고전 10:11", "연결점":"저희에게 일어난 이런 일은 본보기가 되고 또한 말세를 만난 우리를 깨우치기 위하여 기록되었느니라", "구분":"신약"},
        {"구절":"갈 3:8", "연결점":"성경이 하나님이 이방인을 믿음으로 말미암아 의롭다 하실 것을 미리 알고 - 성경의 미래 지향적 목적", "구분":"신약"},
        {"구절":"히 11:39-40", "연결점":"이 사람들이 다 믿음으로 말미암아 증거를 받았으나 ... 우리로 완전함을 이루지 못하게 하려 하심이니라 - 믿음의 선진들이 우리와 연결됨", "구분":"신약"}
    ]
};

pastorCommentaryData["로마서_4_24"] = {
    본문: "의로 여기심을 받을 우리도 위한 것이니 곧 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿는 자니라",
    표1_원어분석: [
        {"원어":"τοῖς πιστεύουσιν ἐπὶ τὸν ἐγείραντα Ἰησοῦν (토이스 피스튜우신 에피 톤 에게이란타 이에순)", "의미_문법":"예수를 살리신 이를 믿는 자들 - 에피 + 목적격은 ~위에/~을 향하여 믿음. 에게이란타는 에게이로(ἐγείρω) 부정과거 분사, 일으키다/살리다", "설교포인트":"복음의 믿음의 대상 - 예수를 살리신 하나님을 믿음"},
        {"원어":"ἐκ νεκρῶν (에크 네크론)", "의미_문법":"죽은 자 가운데서 - 에크(ἐκ)는 ~에서 나와서. 죽음의 영역에서 완전히 나오심", "설교포인트":"부활 - 죽음의 영역에서 완전히 나오심"},
        {"원어":"Ἰησοῦν τὸν κύριον ἡμῶν (이에순 톤 퀴리온 헤몬)", "의미_문법":"예수 우리 주 - 퀴리오스(κύριος)는 주님, 절대적 권위자. 헤몬은 우리의, 개인적 소유를 강조", "설교포인트":"예수는 우리의 주님 - 신앙고백적 선언"}
    ],
    표2_역사적배경: [
        {"항목":"부활 신앙의 중심성", "내용":"초대 교회 신앙고백의 핵심은 예수 그리스도의 부활. 롬 10:9에서도 예수를 주로 시인하고 하나님이 저를 죽은 자 가운데서 살리신 것을 마음에 믿으면 구원을 얻으리라. 부활이 기독교 신앙의 핵심", "목회적활용":"부활 중심의 신앙과 설교"},
        {"항목":"아브라함의 믿음과 부활 신앙의 연결", "내용":"아브라함이 믿은 죽은 자를 살리시는 하나님(롬 4:17)이 바로 예수를 죽은 자 가운데서 살리신 하나님. 아브라함의 믿음과 우리의 믿음의 연속성", "목회적활용":"구약의 믿음과 신약의 믿음의 연속성"}
    ],
    표3_신학적의미: [
        {"교리":"기독교 신앙의 핵심 - 부활", "설명":"기독교 신앙은 예수의 가르침이나 도덕 원리에 대한 동의가 아니라 역사적 사건(예수의 부활)을 이루신 하나님을 믿는 것. 부활 신앙이 없으면 기독교 신앙이 아님 (고전 15:14)", "관련구절":"고전 15:14; 롬 10:9"},
        {"교리":"아브라함의 믿음과의 연속성", "설명":"아브라함이 죽은 자를 살리시는 하나님을 믿음(롬 4:17)과 우리가 예수를 살리신 하나님을 믿음이 본질적으로 동일한 믿음. 구속사의 연속성과 진보", "관련구절":"롬 4:17; 히 11:19"}
    ],
    표4_예표론: [
        {"구분":"이삭 살리심 → 예수 부활", "내용":"아브라함이 이삭을 죽은 자에게서 돌려 받음 (히 11:19)은 예수의 부활의 예표. 죽은 것에서 살리시는 하나님의 행위가 이삭에서 예수로 완성됨", "그리스도연결":"히 11:19 저가 하나님이 능히 죽은 자 가운데서 살리실 줄로 생각한지라 - 아브라함의 믿음이 예수 부활 신앙의 예표"}
    ],
    표5_매튜헨리: [
        {"영어원문":"For us also, to whom it shall be imputed, if we believe on him that raised up Jesus our Lord from the dead. The object of our faith is the same God who justifies by raising the dead, as he raised Jesus.", "한국어번역":"우리에게도 의로 여기심을 받을 것이니 곧 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿으면 된다. 우리 믿음의 대상은 죽은 자를 살리심으로 의롭다 하시는 동일한 하나님이시니, 예수를 살리신 것처럼.", "핵심통찰":"아브라함의 믿음의 하나님과 우리의 믿음의 하나님이 동일함 - 죽은 자를 살리시는 분"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"예수를 살리신 이를 믿는 우리 - 아브라함 칭의의 우리 적용 (롬 4:24)", "예화_적용":"아브라함의 이야기가 예수 부활 신앙을 통해 우리의 이야기가 됨"},
        {"대지":"서론", "내용":"23절에서 아브라함의 칭의 기사가 우리를 위한 것이라고 했다. 그렇다면 우리는 무엇을 믿는 자인가? 바울은 명확히 답한다: 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿는 자", "예화_적용":"복음의 핵심 선언 - 예수 그리스도의 부활"},
        {"대지":"1대지: 우리 믿음의 내용 - 예수 부활", "내용":"기독교 신앙의 핵심은 예수의 부활. 윤리적 가르침이나 종교적 체험이 아니라 역사적 사건(부활)이 믿음의 내용. 고전 15:14 그리스도께서 만일 다시 살지 못하셨으면 우리의 전파하는 것도 헛것이요", "예화_적용":"부활이 없으면 기독교는 아무것도 아님"},
        {"대지":"2대지: 예수 우리 주 - 신앙고백적 선언", "내용":"Ἰησοῦν τὸν κύριον ἡμῶν - 예수는 우리의 주님. 역사적 예수에 대한 사실적 믿음이 개인적 고백(우리 주)으로 이어짐. 롬 10:9 예수를 주로 시인하면", "예화_적용":"역사적 사실 + 개인적 고백 = 구원의 믿음"},
        {"대지":"결론", "내용":"아브라함의 이야기는 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿는 우리의 이야기다. 부활 신앙이 칭의의 근거다. 예수를 주로 고백하는 자가 아브라함과 같은 칭의를 받는다", "예화_적용":"롬 10:9 네가 만일 네 입으로 예수를 주로 시인하며 ... 구원을 얻으리라"}
    ],
    표7_찬송가: [
        {"새찬송가":"160", "통일찬송가":"161", "제목":"예수 부활했으니", "선정이유":"예수 부활이 신앙의 핵심 - 죽은 자를 살리신 하나님"},
        {"새찬송가":"165", "통일찬송가":"166", "제목":"부활절 아침에", "선정이유":"예수를 죽은 자 가운데서 살리신 하나님을 믿는 기쁨"},
        {"새찬송가":"289", "통일찬송가":"405", "제목":"예수 믿으면 구원 얻고", "선정이유":"예수를 우리 주로 믿음으로 구원을 얻음"}
    ],
    표8_상담적용: [
        {"상황":"기독교를 도덕적 삶의 지침 정도로 생각하는 성도", "성경원리":"기독교 믿음의 내용은 예수를 죽은 자 가운데서 살리신 하나님을 믿는 것 (롬 4:24). 역사적 부활 사건이 핵심", "실제적용":"기독교의 핵심이 예수 그리스도의 부활이라는 역사적 사건에 근거함을 설명하고 이 사실을 개인적으로 믿는 신앙으로 초청"},
        {"상황":"예수님을 막연히 믿지만 구체적 믿음의 내용이 없는 성도", "성경원리":"믿음의 내용 - 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿음 (롬 4:24). 믿음의 구체적 내용이 있어야 함", "실제적용":"예수 그리스도의 죽음과 부활의 역사적 사실과 그 의미를 구체적으로 가르치고 예수를 나의 주로 고백하는 개인적 믿음으로 인도"}
    ],
    표9_교차참조: [
        {"구절":"롬 10:9", "연결점":"네가 만일 네 입으로 예수를 주로 시인하며 또 하나님이 그를 죽은 자 가운데서 살리신 것을 네 마음에 믿으면 구원을 얻으리라", "구분":"신약"},
        {"구절":"고전 15:14", "연결점":"그리스도께서 만일 다시 살지 못하셨으면 우리의 전파하는 것도 헛것이요 - 부활의 중심성", "구분":"신약"},
        {"구절":"행 2:32", "연결점":"이 예수를 하나님이 살리신지라 우리가 다 이 일에 증인이로다 - 베드로의 부활 증언", "구분":"신약"},
        {"구절":"히 11:19", "연결점":"저가 하나님이 능히 죽은 자 가운데서 살리실 줄로 생각한지라 - 아브라함의 믿음이 부활 신앙의 예표", "구분":"신약"},
        {"구절":"롬 4:17", "연결점":"죽은 자를 살리시며 없는 것을 있는 것같이 부르시는 이시니라 - 아브라함이 믿은 동일한 하나님", "구분":"신약"}
    ]
};

pastorCommentaryData["로마서_4_25"] = {
    본문: "예수는 우리 범죄함을 위하여 내어 줌이 되고 또한 우리를 의롭다 하심을 위하여 살아나셨느니라",
    표1_원어분석: [
        {"원어":"ὃς παρεδόθη διὰ τὰ παραπτώματα ἡμῶν (호스 파레도데 디아 타 파라프토마타 헤몬)", "의미_문법":"우리 범죄함을 위하여 내어 줌이 되고 - 파레도데는 파라디도미(παραδίδωμι) 부정과거 수동태, 넘겨지다/내어 주어지다. 신적 수동태로 하나님이 내어 주심. 파라프토마(παράπτωμα)는 옆으로 넘어짐, 허물, 범죄", "설교포인트":"그리스도의 죽음의 목적 - 우리의 범죄함을 위하여"},
        {"원어":"ἠγέρθη διὰ τὴν δικαίωσιν ἡμῶν (에게르데 디아 텐 디카이오신 헤몬)", "의미_문법":"우리를 의롭다 하심을 위하여 살아나셨다 - 에게르데는 에게이로(ἐγείρω) 부정과거 수동태, 일으켜지다. 디카이오시스(δικαίωσις)는 칭의, 의롭다 함", "설교포인트":"그리스도의 부활의 목적 - 우리의 칭의를 위하여"},
        {"원어":"διά (디아)", "의미_문법":"두 번 사용 - ~ 때문에/~ 위하여. 죽음은 범죄 때문에, 부활은 칭의를 위하여. 그리스도의 사역의 두 측면", "설교포인트":"죽음과 부활의 두 목적 - 속죄와 칭의"}
    ],
    표2_역사적배경: [
        {"항목":"이사야 53장과의 연결", "내용":"파레도데(내어 줌이 되고)는 이사야 53:12의 그가 자기 영혼을 버려 사망에 이르게 하며의 영어 LXX 번역인 παρεδόθη와 연결. 그리스도의 죽음이 이사야 53장의 성취임을 암시", "목회적활용":"그리스도의 죽음의 구약적 예고와 성취"},
        {"항목":"죽음과 부활의 분리된 역할", "내용":"사도 바울은 죽음(속죄/범죄의 처리)과 부활(칭의)을 구분하여 제시. 그리스도의 사역의 두 단계가 각각 다른 목적을 위함. 그러나 불가분리적으로 연결됨", "목회적활용":"십자가와 부활을 분리하지 말고 함께 가르쳐야 함"}
    ],
    표3_신학적의미: [
        {"교리":"속죄와 칭의의 두 측면", "설명":"죽음 - 우리의 범죄(παραπτώματα)를 처리함(속죄). 부활 - 우리의 칭의(δικαίωσις)를 이룸. 그리스도의 사역 전체가 우리의 완전한 구원을 이룸. 죽음 없이 부활도 없고, 속죄 없이 칭의도 없음", "관련구절":"고전 15:3-4; 롬 5:1"},
        {"교리":"부활의 칭의론적 의미", "설명":"부활이 단지 죽음을 이긴 증거가 아니라 우리의 칭의를 위한 것. 그리스도가 부활하심으로써 의롭다 하심을 위한 새 생명을 이루심. 부활이 칭의의 토대", "관련구절":"고전 15:17; 롬 5:10"}
    ],
    표4_예표론: [
        {"구분":"속죄 제물과 제사장 → 그리스도의 죽음과 부활", "내용":"구약의 속죄 제물은 백성의 죄를 덮었고(롬 4:7), 대제사장은 지성소에 들어가 하나님 앞에 섰음. 그리스도는 제물로 죽으시고(속죄) 대제사장으로 부활하여 하나님 앞에 서심(칭의)", "그리스도연결":"히 9:11-12 그리스도는 장래 좋은 일의 대제사장으로 오사 ... 단번에 성소에 들어가심"}
    ],
    표5_매튜헨리: [
        {"영어원문":"Who was delivered for our offences, and was raised again for our justification. His death was the ground of our pardon; his resurrection was the ground of our justification - both are necessary for our salvation.", "한국어번역":"예수는 우리의 범죄함을 위하여 내어 주셨고 우리의 칭의를 위하여 살아나셨다. 그의 죽음은 우리의 사면의 근거이고; 그의 부활은 우리의 칭의의 근거다 - 둘 다 우리의 구원을 위해 필요하다.", "핵심통찰":"죽음 = 속죄의 근거, 부활 = 칭의의 근거 - 둘 다 구원을 위해 필수"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"내어 주심과 살아나심 - 십자가와 부활의 두 목적 (롬 4:25)", "예화_적용":"속죄(죽음)와 칭의(부활) - 그리스도 사역의 두 기둥"},
        {"대지":"서론", "내용":"4장을 마무리하는 이 절은 기독교 복음의 핵심을 두 문장으로 압축한다. 예수는 두 가지 일을 하셨다: 우리 범죄함을 위해 내어 주심이 되고, 우리 칭의를 위해 살아나심. 이 두 사건이 우리 구원의 전부다", "예화_적용":"두 개의 기둥이 다리를 지탱하듯 십자가와 부활이 구원을 지탱함"},
        {"대지":"1대지: 우리 범죄함을 위하여 내어 줌이 되심", "내용":"파라디도미 신적 수동태 - 아버지가 아들을 내어 주심 (요 3:16; 롬 8:32). 우리의 모든 범죄가 그에게 넘겨짐. 그가 우리의 죄의 값을 치르심. 이것이 십자가의 속죄", "예화_적용":"죄의 청구서가 그리스도에게 돌려짐"},
        {"대지":"2대지: 우리 칭의를 위하여 살아나심", "내용":"에게르데 - 살아나심, 일으켜지심. 부활이 우리의 칭의를 위한 것. 그리스도의 부활은 칭의의 선언 - 하나님이 그리스도의 속죄를 받으시고 의롭다 하셨음의 증거. 우리도 그 안에서 의롭다 하심을 받음", "예화_적용":"재판 후 석방 - 부활은 무죄 판결의 집행"},
        {"대지":"결론", "내용":"예수는 우리를 위해 두 가지를 하셨다. 우리 죄를 위해 죽으시고, 우리 의를 위해 사셨다. 이 두 사건이 우리 구원의 완전한 토대다. 십자가와 부활을 함께 붙들라", "예화_적용":"고전 15:3-4 내가 받은 것을 먼저 너희에게 전하였노니 그것은 그리스도께서 우리 죄를 위하여 죽으시고 ... 다시 살아나셨다 하는 것이라"}
    ],
    표7_찬송가: [
        {"새찬송가":"150", "통일찬송가":"144", "제목":"갈보리산 위에", "선정이유":"우리 죄를 위해 내어 주셔진 십자가"},
        {"새찬송가":"160", "통일찬송가":"161", "제목":"예수 부활했으니", "선정이유":"우리 칭의를 위해 살아나신 예수"},
        {"새찬송가":"167", "통일찬송가":"168", "제목":"주 예수 크신 사랑", "선정이유":"죽음과 부활을 통해 나타난 그리스도의 크신 사랑"}
    ],
    표8_상담적용: [
        {"상황":"죄책감에서 벗어나지 못하는 성도", "성경원리":"예수는 우리 범죄함을 위하여 내어 주셨음 (롬 4:25). 우리 죄의 값이 이미 치러짐", "실제적용":"그리스도의 속죄가 이미 완성된 사실임을 확인하고 그 위에 서도록 도움. 고후 5:21, 히 10:10-14로 속죄의 완전성을 확인"},
        {"상황":"칭의는 알겠는데 실제 삶에서 의롭지 않음을 느끼는 성도 (칭의와 성화의 혼동)", "성경원리":"칭의는 부활하신 그리스도 안에서의 법정적 선언 (롬 4:25). 내 느낌이 아닌 그리스도의 부활로 확증된 하나님의 선언이 근거", "실제적용":"칭의(하나님의 선언)와 성화(삶의 변화)를 구분하여 설명하고 칭의는 완성된 사실이지만 성화는 과정임을 가르침. 이 긴장 속에서 그리스도를 바라보도록 안내"}
    ],
    표9_교차참조: [
        {"구절":"사 53:5-6", "연결점":"그가 찔림은 우리의 허물을 인함이요 ... 여호와께서는 우리 무리의 죄악을 그에게 담당시키셨도다 - 내어 주심의 예표", "구분":"구약"},
        {"구절":"롬 8:32", "연결점":"자기 아들을 아끼지 아니하시고 우리 모든 사람을 위하여 내어 주신 이 - 내어 주심의 신적 능동적 측면", "구분":"신약"},
        {"구절":"고전 15:3-4", "연결점":"그리스도께서 우리 죄를 위하여 죽으시고 ... 다시 살아나셨다 - 죽음과 부활의 핵심 선언", "구분":"신약"},
        {"구절":"고전 15:17", "연결점":"그리스도께서 다시 살지 못하셨으면 너희의 믿음도 헛되고 너희가 여전히 죄 가운데 있을 것이요 - 부활이 없으면 칭의도 없음", "구분":"신약"},
        {"구절":"롬 5:1", "연결점":"그러므로 우리가 믿음으로 의롭다 하심을 얻었은즉 우리 주 예수 그리스도로 말미암아 하나님으로 더불어 화평을 누리자 - 칭의의 결과", "구분":"신약"}
    ]
};
